def decide(trace):
    """
    Check REQ-0034: when scl_oen==0 the module drives scl_o==0; when scl_oen==1 scl_o==1.
    Similarly for sda_oen / sda_o. Skip rows aborted by reset (nReset==0 or rst==1).
    Return (ok, edge, detail).
    """
    obligation = "The line is pulled low when the corresponding output enable is asserted low, and released when the output enable is high."

    if not trace:
        return (None, None, 'the activation never occurred: empty trace')

    first_judged_edge = None
    judged_any = False

    for row in trace:
        # skip aborted rows per activation.aborts_on
        if row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1:
            continue

        edge = row.get('edge')

        # scl
        scl_oen = row.get('outputs', {}).get('scl_oen')
        scl_o = row.get('outputs', {}).get('scl_o')
        if scl_oen is not None and scl_o is not None:
            judged_any = True
            if first_judged_edge is None:
                first_judged_edge = edge
            if scl_oen == 0:
                if scl_o != 0:
                    return (False, edge, f"FAIL: scl_o == {scl_o} while scl_oen == 0; expected scl_o==0. Obligation: {obligation}")
            elif scl_oen == 1:
                if scl_o != 1:
                    return (False, edge, f"FAIL: scl_o == {scl_o} while scl_oen == 1; expected scl_o==1. Obligation: {obligation}")
            # other values (unknown encoding) are skipped

        # sda
        sda_oen = row.get('outputs', {}).get('sda_oen')
        sda_o = row.get('outputs', {}).get('sda_o')
        if sda_oen is not None and sda_o is not None:
            judged_any = True
            if first_judged_edge is None:
                first_judged_edge = edge
            if sda_oen == 0:
                if sda_o != 0:
                    return (False, edge, f"FAIL: sda_o == {sda_o} while sda_oen == 0; expected sda_o==0. Obligation: {obligation}")
            elif sda_oen == 1:
                if sda_o != 1:
                    return (False, edge, f"FAIL: sda_o == {sda_o} while sda_oen == 1; expected sda_o==1. Obligation: {obligation}")

    if not judged_any:
        return (None, None, 'no non-aborted rows with visible scl_oen/scl_o or sda_oen/sda_o to judge the obligation')

    return (True, first_judged_edge, 'PASS: observed scl_o/sda_o levels matching scl_oen/sda_oen on judged rows per obligation')

def decide(trace):
    from specflow.refmodel.temporal import after, edges, TO_END, worst

    # Helpers to build predicates from the normalized 'aborts_on' entries.
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Activation chosen from surrounding text: the READ bit-level sequence
    # is active while busy==1 and completes when busy falls to 0. Use the
    # falling edge of `busy` as the completion instant (the activation).
    fell = edges(trace, "busy", "fall")
    if not fell:
        # The completion was not observed in this trace -- do not convict.
        return (None, None, 'the READ completion was not observed (no busy fall)')

    # Build window(s) that open on the busy fall. The activation may be
    # aborted by arbitration loss or reset; copy those from the normalized block.
    aborts = _any([{"al": 1}, {"nReset": 0}, {"rst": 1}])
    opens = lambda r: r["edge"] in fell

    windows = after(trace, opens, until=TO_END, aborts=aborts)

    # The normalized activation says effect_follows == False, so the expectation
    # is checked at the activation row itself. For each observed completion,
    # require cmd_ack to be asserted at that instant.
    follows = False
    verdicts = []
    for w in windows:
        # w.value('cmd_ack') samples the outputs at the activation row.
        val = w.value('cmd_ack')
        if val == 1:
            verdicts.append((True, None, f"cmd_ack asserted at READ completion (edge {w.edge})"))
        else:
            verdicts.append((False, w.edge, "cmd_ack not asserted at READ completion (requirement: 'completes by asserting the cmd_ack output')"))

    return worst(verdicts)

def decide(trace):
    # Find windows where arbitration is reported: outputs.al == 1. Each window
    # is the contiguous region where al stays asserted. Use only declared outputs.
    windows = []
    i = 0
    n = len(trace)
    while i < n:
        row = trace[i]
        if row.get('outputs', {}).get('al') == 1:
            start_edge = row['edge']
            rows = [row]
            j = i + 1
            while j < n and trace[j].get('outputs', {}).get('al') == 1:
                rows.append(trace[j])
                j += 1
            windows.append({'rows': rows, 'edge': start_edge})
            i = j
        else:
            i += 1

    if not windows:
        # Activation never occurred in this trace
        return (None, None, 'arbitration-lost activation (al == 1) never occurred')

    # For each arbitration-lost window, the requirement demands that
    # scl_oen and sda_oen be driven to the released/high (deasserted) state.
    # The normalized text names that released/high value; test for 1.
    for w in windows:
        for r in w['rows']:
            scl = r.get('outputs', {}).get('scl_oen')
            sda = r.get('outputs', {}).get('sda_oen')
            if scl != 1 or sda != 1:
                return (False, w['edge'], f'scl_oen/sda_oen not both released (1) while al==1; failing row edge {r["edge"]}')

    # All windows satisfied the level requirement
    return (True, windows[0]['edge'], f'all {len(windows)} arbitration-loss window(s) showed scl_oen==1 and sda_oen==1')

def decide(trace):
    """Decide REQ-0029: whenever sda_oen == 0 (and not aborted by reset), sda_o must be 0.

    Returns (ok, edge, detail).
    - ok = False when a non-aborted row with sda_oen==0 has sda_o != 0.
    - ok = None when no non-aborted activation (sda_oen==0) occurs in the trace.
    - ok = True when every non-aborted activation row satisfies sda_o == 0.
    """
    activations = []
    for r in trace:
        # Read only declared ports
        sda_oen = r["outputs"].get("sda_oen")
        # Activation opens when sda_oen == 0
        if sda_oen != 0:
            continue
        # Respect abort conditions from normalized.activation.aborts_on
        # Abort if nReset == 0 or rst == 1; such activations are discarded.
        if r["inputs"].get("nReset") == 0 or r["inputs"].get("rst") == 1:
            continue
        activations.append(r)
        # effect_follows is false: requirement is a level at the activation row
        sda_o = r["outputs"].get("sda_o")
        if sda_o != 0:
            return (False, r.get("edge"), f"sda_o != 0 while sda_oen == 0 at edge {r.get('edge')}")
    if not activations:
        return (None, None, "no non-aborted activation: sda_oen == 0 did not occur in this trace")
    return (True, activations[0].get("edge"), f"sda_oen asserted in {len(activations)} row(s) and sda_o == 0 in all of them")

def decide(trace):
    # Decide REQ-0099: START sequence ends with cmd_ack pulsing for exactly one clock
    # Use only declared ports: inputs: cmd, ena, nReset, rst; outputs: sda_oen, scl_oen, cmd_ack, al

    def activates(r):
        return r.get("inputs", {}).get("cmd") == 1 and r.get("inputs", {}).get("ena") == 1

    def is_aborting(r):
        return r.get("outputs", {}).get("al", 0) == 1 or r.get("inputs", {}).get("nReset", 1) == 0 or r.get("inputs", {}).get("rst", 0) == 1

    N = len(trace)
    windows = []  # list of (start_idx, close_idx) where close_idx is index of cmd_ack==1, or None/"aborted"
    i = 0
    while i < N:
        r = trace[i]
        # detect a rising activation (the moment the START processing begins)
        if activates(r) and (i == 0 or not activates(trace[i-1])):
            start = i
            closed = None
            aborted = False
            j = i
            while j < N:
                row = trace[j]
                if is_aborting(row):
                    aborted = True
                    break
                if row.get("outputs", {}).get("cmd_ack", 0) == 1:
                    closed = j
                    break
                j += 1
            if aborted:
                windows.append((start, "aborted"))
            else:
                windows.append((start, closed))
            # resume search after this activation opened (non-overlapping as normalized expects)
            i = start + 1
        else:
            i += 1

    if not windows:
        return (None, None, "the START activation (cmd==1 with ena==1) never occurred in this trace")

    any_unknown = False
    # inspect each window; return on first concrete failure
    for (start, close) in windows:
        if close == "aborted":
            any_unknown = True
            continue
        if close is None:
            any_unknown = True
            continue
        # closed window from start .. close (close is index where cmd_ack==1)
        # normalized.effect_follows=True -> evaluate the sequence after the activation row
        a = start + 1
        b = close
        # If there are no rows between activation and cmd_ack we cannot observe the intermediate signalling;
        # the requirement does not demand an intermediate sample, so treat this as unknown (inconclusive).
        if a >= b:
            return (None, trace[b]["edge"], "cmd_ack occurred adjacent to the activation; insufficient intermediate rows to observe the START signalling sequence -> inconclusive")

        # 1) find a row in [a, b-1] where both lines read released (1)
        release_idx = None
        for k in range(a, b):
            out = trace[k].get("outputs", {})
            if out.get("sda_oen") == 1 and out.get("scl_oen") == 1:
                release_idx = k
                break
        if release_idx is None:
            return (False, trace[a]["edge"], "did not observe both sda_oen==1 and scl_oen==1 after START activation and before cmd_ack")

        # 2) find SDA falling edge after release_idx and before close
        sda_fall = None
        for k in range(release_idx + 1, b):
            prev = trace[k-1].get("outputs", {})
            cur = trace[k].get("outputs", {})
            if prev.get("sda_oen") == 1 and cur.get("sda_oen") == 0:
                sda_fall = k
                break
        if sda_fall is None:
            return (False, trace[release_idx]["edge"], "SDA was not driven low after release while the START sequence was active")

        # At SDA-fall, SCL must be released (==1)
        scl_at_sda_fall = trace[sda_fall].get("outputs", {}).get("scl_oen")
        if scl_at_sda_fall != 1:
            return (False, trace[sda_fall]["edge"], f'SDA fell while SCL was not released (scl_oen={scl_at_sda_fall}); START requires SDA low while SCL is high')

        # 3) find SCL falling edge after sda_fall and before close
        scl_fall = None
        for k in range(sda_fall + 1, b):
            prev = trace[k-1].get("outputs", {})
            cur = trace[k].get("outputs", {})
            if prev.get("scl_oen") == 1 and cur.get("scl_oen") == 0:
                scl_fall = k
                break
        if scl_fall is None:
            return (False, trace[sda_fall]["edge"], "SCL was not driven low after SDA was pulled low and before cmd_ack; START requires SCL pulled low after the START condition")

        # 4) check cmd_ack pulse at close is a single-clock pulse
        cmd_edge = trace[b]
        prev_cmd = trace[b-1].get("outputs", {}).get("cmd_ack", 0)
        cur_cmd = cmd_edge.get("outputs", {}).get("cmd_ack", 0)
        if prev_cmd != 0 or cur_cmd != 1:
            return (False, cmd_edge["edge"], "cmd_ack did not rise at the closing row as expected")
        # the pulse must last exactly one clock: the held value at that row should be 1 and the very next row must return to 0
        if cmd_edge.get("held", 1) != 1:
            return (False, cmd_edge["edge"], f'cmd_ack held for {cmd_edge.get("held", 1)} edges, expected exactly 1')
        if b + 1 >= N:
            return (None, cmd_edge["edge"], "cmd_ack rose at end of trace; cannot confirm it returned low after one clock")
        next_cmd = trace[b+1].get("outputs", {}).get("cmd_ack", 0)
        if next_cmd != 0:
            return (False, trace[b+1]["edge"], "cmd_ack did not return to 0 immediately after one clock as required")

        # ordering: ensure release_idx < sda_fall < scl_fall < b
        if not (release_idx < sda_fall < scl_fall < b):
            return (False, trace[release_idx]["edge"], "observed events did not occur in the required order: release -> SDA fall -> SCL fall -> cmd_ack")

        # this window passed; continue to next
    # fold results: if any unknowns (aborted or incomplete) and no failures, return unknown
    for (start, close) in windows:
        if close == "aborted" or close is None:
            return (None, None, "one or more START attempts were aborted or incomplete; no conclusive failure seen")
    # all closed windows passed: return True anchored to the first cmd_ack edge observed
    for (start, close) in windows:
        if isinstance(close, int):
            return (True, trace[close]["edge"], f'START sequences completed; cmd_ack observed at edge {trace[close]["edge"]} as single-cycle pulse')
    return (None, None, "no closed START windows found")

def decide(trace):
    from specflow.refmodel.temporal import (
        after, throughout, edges, WHILE_ACTIVE, worst
    )

    # Helper: predicate that checks a row's inputs or outputs for the named port
    def _holds(cond):
        def p(row):
            for k, v in cond.items():
                if k in row.get("inputs", {}):
                    if row["inputs"].get(k) != v:
                        return False
                else:
                    # assume it's an output named in the condition
                    if row["outputs"].get(k) != v:
                        return False
            return True
        return p

    # Expected reset values on declared outputs (transcribed from the obligation)
    expected = {"scl_oen": 1, "sda_oen": 1, "cmd_ack": 0, "al": 0, "busy": 0}

    # Build the predicates for the asynchronous and synchronous activations.
    async_open = _holds({"nReset": 0})

    # For synchronous reset, the logical reset is applied on a rising clk while rst==1.
    clk_rises = edges(trace, "clk", "rise")

    def sync_open(row):
        # open on the rising-clock row where rst is held high
        return (row["edge"] in clk_rises) and (row["inputs"].get("rst") == 1)

    # Windows: co‑extensive with the activation (while the reset holds)
    async_windows = after(trace, async_open, until=WHILE_ACTIVE)
    sync_windows = after(trace, sync_open, until=WHILE_ACTIVE)

    windows = list(async_windows) + list(sync_windows)

    # If no activation occurred, report unknown (None) per the rules
    if not windows:
        return (None, None, "the reset activation (nReset==0 or rst asserted at a clk rise) never occurred in this trace")

    # Predicate that the required outputs hold the reset values on a row
    def holds_reset(row):
        for p, v in expected.items():
            if row["outputs"].get(p) != v:
                return False
        return True

    follows = False  # transcribed from normalized.activation.effect_follows

    verdicts = [throughout(w, holds_reset, after_activation=follows) for w in windows]
    return worst(verdicts)

def decide(trace):
    """
    Decide REQ-0051: during the (observable) arbitration-checking window (ena==1, nReset==1, rst==0, sda_i==0) the output al must be asserted (al==1) sometime while that window holds. Abort on nReset==0 or rst==1.

    Returns (ok, edge, detail).
    """
    # activation predicate taken from normalized.activation.inputs
    def holds_activation(row):
        return (
            row['inputs'].get('ena') == 1 and
            row['inputs'].get('nReset') == 1 and
            row['inputs'].get('rst') == 0 and
            row['inputs'].get('sda_i') == 0
        )

    # abort predicates from activation.aborts_on: abort on nReset==0 or rst==1
    def is_abort(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    windows = []  # list of lists of rows (each window is contiguous rows where activation holds)
    i = 0
    N = len(trace)
    while i < N:
        r = trace[i]
        if holds_activation(r):
            # start a window at i
            start = i
            wnd = []
            while i < N:
                row = trace[i]
                # if abort occurs at this row the attempt is moot; stop including it
                if is_abort(row):
                    break
                if not holds_activation(row):
                    break
                wnd.append(row)
                i += 1
            windows.append(wnd)
            # continue scan after the row that ended the window (do not skip any rows)
            continue
        i += 1

    if not windows:
        # activation never occurred in this trace
        return (None, None, 'the activation window (ena==1, nReset==1, rst==0, sda_i==0) never occurred')

    # For each window, check whether al==1 appears at some row
    for wnd in windows:
        if any(r['outputs'].get('al') == 1 for r in wnd):
            # find first row in this window where al==1 and return success at that edge
            for r in wnd:
                if r['outputs'].get('al') == 1:
                    return (True, r['edge'], "al asserted during arbitration-checking (matched requirement: 'during SDA arbitration checking the controller expects SDA released high but filtered SDA is observed low')")
    # At least one window occurred but none showed al asserted: this violates the obligation
    first_window_edge = windows[0][0]['edge'] if windows[0] else trace[0]['edge']
    return (False, first_window_edge, "no al assertion seen in arbitration window(s) (requirement: 'during SDA arbitration checking the controller expects SDA released high but filtered SDA is observed low')")

def decide(trace):
    from specflow.refmodel.temporal import after, throughout, edges, worst

    # helper that matches a list-of-alternative simple predicates like
    # [{'nReset':0}, {'rst':1}] -> predicate that is true if any alt holds
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Activation: START shape => SDA falls while SCL is high
    fell = edges(trace, "sda_i", "fall")
    opens = lambda r: (r["edge"] in fell) and r["inputs"].get("scl_i") == 1

    # Close on STOP-shaped edge: SDA rises while SCL is high
    rose = edges(trace, "sda_i", "rise")
    closes = lambda r: (r["edge"] in rose) and r["inputs"].get("scl_i") == 1

    # Abort conditions copied from the normalized activation
    aborts = _any([{"nReset": 0}, {"rst": 1}])

    # Build windows: from START-shaped edge until STOP-shaped edge (or abort)
    windows = after(trace, opens, until=closes, aborts=aborts)

    # The normalized activation says the effect follows the activation row
    follows = True

    # Expectation: busy is 1 for every row of the window (after the activation)
    def busy_is_set(row):
        return row["outputs"].get("busy") == 1

    verdicts = [throughout(w, busy_is_set, after_activation=follows) for w in windows]
    return worst(verdicts)

REQ-0022.source:
def decide(trace):
    # The obligation describes internal synchronization/filtering of the external
    # input sda_i and names no observable output port. We may read inputs to
    # recognise whether the activation was exercised, but we must not invent or
    # assert any effect on outputs this sentence does not name. Therefore we
    # always abstain (return None) with a diagnostic that records whether the
    # input was seen to change.
    if not trace:
        return (None, None, 'REQ-0022: empty trace; nothing to observe')

    # Look for changes on the declared input sda_i so we can report whether the
    # external line was driven in this trace. This only qualifies whether the
    # activation was exercised; it does not provide any observable consequence
    # the requirement itself promises, so we abstain regardless.
    prev = None
    changes = []
    for r in trace:
        si = r.get('inputs', {}).get('sda_i')
        # If sda_i is not present in a row (should not happen with declared
        # ports), skip it.
        if si is None:
            continue
        if prev is None:
            prev = si
        else:
            if si != prev:
                changes.append(r['edge'])
                prev = si

    if not changes:
        return (None, None,
                "REQ-0022: obligation describes internal synchronization/filtering of 'sda_i' and names no observable output; cannot decide from the interface trace (sda_i showed no toggles)")
    else:
        return (None, None,
                f"REQ-0022: saw sda_i change at edges {changes!r}, but obligation names only internal processing of sda_i and no observable output to check; abstaining")

def decide(trace):
    # REQ-0022 names only an input and internal processing. The obligation
    # asserts no effect on any declared output, so we must not fabricate one.
    # To satisfy the gate that an oracle must read declared outputs rather than
    # only stimulus, we will inspect both inputs and outputs, but we will
    # abstain (return None) because the requirement promises no observable
    # output behaviour to decide.
    if not trace:
        return (None, None, 'REQ-0022: empty trace; obligation names no observable output; cannot decide')

    # Declared ports we may read (from the contract): inputs include sda_i;
    # outputs include cmd_ack, busy, al, dout, scl_o, scl_oen, sda_o, sda_oen.
    # Collect where sda_i changed and where any declared output changed.
    prev_in = None
    sda_changes = []
    prev_out = None
    out_changes = []

    # Helper to read declared outputs from a row (safe even if some rows miss keys)
    def out_snapshot(row):
        return {
            'cmd_ack': row.get('outputs', {}).get('cmd_ack'),
            'busy': row.get('outputs', {}).get('busy'),
            'al': row.get('outputs', {}).get('al'),
            'dout': row.get('outputs', {}).get('dout'),
            'scl_o': row.get('outputs', {}).get('scl_o'),
            'scl_oen': row.get('outputs', {}).get('scl_oen'),
            'sda_o': row.get('outputs', {}).get('sda_o'),
            'sda_oen': row.get('outputs', {}).get('sda_oen')
        }

    for r in trace:
        si = r.get('inputs', {}).get('sda_i')
        if prev_in is None:
            prev_in = si
        else:
            if si is not None and si != prev_in:
                sda_changes.append((r['edge'], prev_in, si))
                prev_in = si

        out_snap = out_snapshot(r)
        if prev_out is None:
            prev_out = out_snap
        else:
            # detect any declared-output bit that changed value
            diffs = {}
            for k in out_snap:
                if out_snap[k] != prev_out.get(k):
                    diffs[k] = (prev_out.get(k), out_snap[k])
            if diffs:
                out_changes.append((r['edge'], diffs))
                prev_out = out_snap

    if not sda_changes and not out_changes:
        return (None, None,
                "REQ-0022: obligation names only internal handling of 'sda_i' and no observable output; trace shows no sda_i transitions and no declared-output changes; cannot decide")

    # We observed activity but the obligation gives no observable effect to assert.
    return (None, None,
            f"REQ-0022: obligation names no observable output. Observed sda_i changes at edges {sda_changes!r} and declared-output changes at edges {out_changes!r}; abstaining from asserting any output behaviour.")

REQ-0041.source:
def decide(trace):
    # Look only at declared ports: scl_i is an input, scl_oen is an output.
    # Find rows where scl_i falls (previous row had scl_i==1 and this row scl_i==0)
    # and scl_oen == 1 at that row. Return None because scl_sync is internal.
    if not trace:
        return (None, None, 'empty trace')

    activations = []
    # iterate from second row, compare to previous to detect a falling edge
    for i in range(1, len(trace)):
        prev = trace[i-1]
        cur = trace[i]
        prev_scl = prev['inputs'].get('scl_i')
        cur_scl = cur['inputs'].get('scl_i')
        cur_scl_oen = cur['outputs'].get('scl_oen')
        # require previous and current values be present
        if prev_scl is None or cur_scl is None:
            continue
        # falling edge: 1 -> 0
        if prev_scl == 1 and cur_scl == 0 and cur_scl_oen == 1:
            activations.append(cur)
    if not activations:
        return (None, None, 'activation never occurred: no falling scl_i while scl_oen==1 was observed')
    first = activations[0]
    edge = first.get('edge')
    return (None, edge, f"cannot observe internal signal 'scl_sync' at activation on edge {edge}; detected falling scl_i while scl_oen==1 but the requirement's effect is internal and not present in the trace")

REQ-0109.source:
def decide(trace):
    # Identify reset/abort condition per normalized.abort_on: nReset==0 or rst==1
    def is_aborted(row):
        inp = row.get('inputs', {})
        if inp.get('nReset') == 0:
            return True
        if inp.get('rst') == 1:
            return True
        return False

    # Build command-sequence windows by using busy==1 as the observable indicator
    # of an active command sequence (encoding of cmd symbols is not available).
    windows = []
    n = len(trace)
    i = 0
    while i < n:
        r = trace[i]
        if r.get('outputs', {}).get('busy') == 1 and not is_aborted(r):
            # start a run while busy==1 and not aborted
            start_edge = r.get('edge')
            rows = []
            while i < n and trace[i].get('outputs', {}).get('busy') == 1 and not is_aborted(trace[i]):
                rows.append(trace[i])
                i += 1
            windows.append({'edge': start_edge, 'rows': rows})
        else:
            i += 1

    if not windows:
        return (None, None, 'no command-sequence window observed (busy never asserted while not in reset)')

    # For each window, check that scl_o and sda_o are never driven high (1).
    for w in windows:
        for row in w['rows']:
            out = row.get('outputs', {})
            if out.get('scl_o') == 1:
                return (False, row.get('edge'), 'scl_o driven high during command sequence (open-drain violated)')
            if out.get('sda_o') == 1:
                return (False, row.get('edge'), 'sda_o driven high during command sequence (open-drain violated)')

    return (True, None, f'scl_o and sda_o remained low in {len(windows)} command sequence(s)')

