def decide(trace):
    """
    The requirement names an internal FSM transition but does not name any declared
    output on which that transition must be visible. We therefore cannot decide
    the obligation from declared ports. To aid debugging we scan the declared
    outputs and return UNKNOWN (ok=None) along with the edge of the first
    observable output change, if any, and a detail string explaining why the
    requirement remains undecidable from the trace.
    """
    declared_outputs = [
        'cmd_ack', 'busy', 'al', 'dout', 'scl_o', 'scl_oen', 'sda_o', 'sda_oen'
    ]

    if not trace:
        return (None, None, 'empty trace; cannot determine FSM decoding from declared ports')

    def _outs(row):
        return {k: row['outputs'].get(k) for k in declared_outputs}

    prev = _outs(trace[0])
    # scan for the first row where any declared output changes value
    for row in trace[1:]:
        cur = _outs(row)
        if cur != prev:
            changed = [k for k in declared_outputs if cur.get(k) != prev.get(k)]
            detail = (
                f'declared outputs changed ({", ".join(changed)}) at edge {row.get("edge")}; '
                "however REQ-0098 names only the internal FSM idle and does not specify which output(s) '
                'should show the decoding, so the obligation is not decidable from the trace'
            )
            return (None, row.get('edge'), detail)
        prev = cur

    # no declared-output change anywhere in the trace
    return (None, trace[0].get('edge'), 'no declared-output activity observed; cannot determine FSM decoding from declared ports')

