def decide(trace):
    # look for changes of scl_oen or sda_oen (activations) and require the
    # corresponding scl_o / sda_o to transition to the expected level at the
    # same row. Skip activations that are aborted by reset (nReset==0 or rst==1).
    if not trace or len(trace) < 2:
        return (None, None, 'the activation never occurred: no change of scl_oen or sda_oen seen')

    activations = []  # tuples: (which, prev_row, cur_row, aborted)
    for i in range(1, len(trace)):
        prev = trace[i-1]
        cur = trace[i]
        # detect scl_oen change
        p = prev['outputs'].get('scl_oen')
        c = cur['outputs'].get('scl_oen')
        if p is not None and c is not None and p != c:
            aborted = (cur['inputs'].get('nReset') == 0) or (cur['inputs'].get('rst') == 1)
            activations.append(('scl', prev, cur, aborted))
        # detect sda_oen change
        p = prev['outputs'].get('sda_oen')
        c = cur['outputs'].get('sda_oen')
        if p is not None and c is not None and p != c:
            aborted = (cur['inputs'].get('nReset') == 0) or (cur['inputs'].get('rst') == 1)
            activations.append(('sda', prev, cur, aborted))

    if not activations:
        return (None, None, 'the activation never occurred: no change of scl_oen or sda_oen seen')

    # If all activations were aborted by reset, the requirement is not judged here
    if all(a[3] for a in activations):
        return (None, None, 'activation(s) were aborted by reset (nReset==0 or rst==1) and are not judged')

    # Check each non-aborted activation. The obligation is an ACTION at the
    # moment of change, so we require a transition of the line at that row.
    obligation_phrase = "The line is pulled low when the corresponding output enable is asserted low, and released when the output enable is high."
    for which, prev, cur, aborted in activations:
        if aborted:
            continue
        edge = cur.get('edge')
        if which == 'scl':
            prev_line = prev['outputs'].get('scl_o')
            cur_line = cur['outputs'].get('scl_o')
            cur_oen = cur['outputs'].get('scl_oen')
        else:
            prev_line = prev['outputs'].get('sda_o')
            cur_line = cur['outputs'].get('sda_o')
            cur_oen = cur['outputs'].get('sda_oen')
        # If any of the necessary values are missing, we cannot judge this activation
        if prev_line is None or cur_line is None or cur_oen is None:
            # treat as unknown for this activation: skip it
            continue
        # when oen goes to 0 we expect the line to transition to 0 at this row
        if cur_oen == 0:
            if not (cur_line == 0 and prev_line != 0):
                return (False, edge, f"FAIL: on activation the {which} output-enable changed to 0 but the corresponding {which}_o did not transition to 0. Obligation: {obligation_phrase}")
        # when oen goes to 1 we expect the line to transition to 1 at this row
        elif cur_oen == 1:
            if not (cur_line == 1 and prev_line != 1):
                return (False, edge, f"FAIL: on activation the {which} output-enable changed to 1 but the corresponding {which}_o did not transition to 1. Obligation: {obligation_phrase}")
        else:
            # unknown encoding; skip this activation
            continue

    # If we reached here at least one non-aborted activation was judged and none failed
    # return success and point at the first judged activation edge
    for which, prev, cur, aborted in activations:
        if not aborted:
            return (True, cur.get('edge'), f"PASS: observed {which}_oen changes with matching {which}_o transitions per obligation: {obligation_phrase}")

    # If no judged activation (e.g. missing values), abstain
    return (None, None, 'no judged activation with sufficient signal visibility was found')

def decide(trace):
    """
    Check REQ-0034: when scl_oen==0 the module drives scl_o==0; when scl_oen==1 scl_o==1.
    Similarly for sda_oen / sda_o. Skip rows aborted by reset (nReset==0 or rst==1).
    Return (ok, edge, detail).
    """
    obligation = "The line is pulled low when the corresponding output enable is asserted low, and released when the output enable is high."

    if not trace:
        return (None, None, 'the activation never occurred: empty trace')

    first_judged_edge = None
    judged_any = False

    for row in trace:
        # skip aborted rows per activation.aborts_on
        if row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1:
            continue

        edge = row.get('edge')

        # scl
        scl_oen = row.get('outputs', {}).get('scl_oen')
        scl_o = row.get('outputs', {}).get('scl_o')
        if scl_oen is not None and scl_o is not None:
            judged_any = True
            if first_judged_edge is None:
                first_judged_edge = edge
            if scl_oen == 0:
                if scl_o != 0:
                    return (False, edge, f"FAIL: scl_o == {scl_o} while scl_oen == 0; expected scl_o==0. Obligation: {obligation}")
            elif scl_oen == 1:
                if scl_o != 1:
                    return (False, edge, f"FAIL: scl_o == {scl_o} while scl_oen == 1; expected scl_o==1. Obligation: {obligation}")
            # other values (unknown encoding) are skipped

        # sda
        sda_oen = row.get('outputs', {}).get('sda_oen')
        sda_o = row.get('outputs', {}).get('sda_o')
        if sda_oen is not None and sda_o is not None:
            judged_any = True
            if first_judged_edge is None:
                first_judged_edge = edge
            if sda_oen == 0:
                if sda_o != 0:
                    return (False, edge, f"FAIL: sda_o == {sda_o} while sda_oen == 0; expected sda_o==0. Obligation: {obligation}")
            elif sda_oen == 1:
                if sda_o != 1:
                    return (False, edge, f"FAIL: sda_o == {sda_o} while sda_oen == 1; expected sda_o==1. Obligation: {obligation}")

    if not judged_any:
        return (None, None, 'no non-aborted rows with visible scl_oen/scl_o or sda_oen/sda_o to judge the obligation')

    return (True, first_judged_edge, 'PASS: observed scl_o/sda_o levels matching scl_oen/sda_oen on judged rows per obligation')

