def decide(trace):
    # This requirement names only the input 'scl_i' and describes internal
    # processing and uses. No observable output is named in the obligation,
    # so the property is not decidable from the module's declared outputs.
    # We still locate activity on declared ports to (a) follow the normalized
    # aborts_on (reset) and (b) give a useful localisation if activity occurs.

    prev = None
    for r in trace:
        # respect abort conditions from the normalized activation
        if r['inputs'].get('nReset') == 0 or r['inputs'].get('rst') == 1:
            # activation aborted by reset; this makes the requirement moot here
            return (None, r['edge'], 'REQ-0021: aborted by reset (nReset==0 or rst==1)')

        s = r['inputs'].get('scl_i')
        # initialise prev on the first row that carries scl_i
        if prev is None:
            prev = s
            continue

        # detect a transition on the declared input scl_i to localise activity
        if s != prev:
            return (None, r['edge'],
                    'REQ-0021: observed scl_i transition at this edge, but obligation names only internal handling of scl_i and no observable output to check; requirement is not decidable from declared I/O')

        prev = s

    # no transition and no reset seen => no activation observable here
    return (None, None, 'REQ-0021: no scl_i transition or reset observed; obligation names only internal handling of scl_i and is not decidable from declared I/O')

