def decide(trace):
    from specflow.refmodel.temporal import after, edges, TO_END, worst

    # Helpers to build predicates from the normalized 'aborts_on' entries.
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Activation chosen from surrounding text: the READ bit-level sequence
    # is active while busy==1 and completes when busy falls to 0. Use the
    # falling edge of `busy` as the completion instant (the activation).
    fell = edges(trace, "busy", "fall")
    if not fell:
        # The completion was not observed in this trace -- do not convict.
        return (None, None, 'the READ completion was not observed (no busy fall)')

    # Build window(s) that open on the busy fall. The activation may be
    # aborted by arbitration loss or reset; copy those from the normalized block.
    aborts = _any([{"al": 1}, {"nReset": 0}, {"rst": 1}])
    opens = lambda r: r["edge"] in fell

    windows = after(trace, opens, until=TO_END, aborts=aborts)

    # The normalized activation says effect_follows == False, so the expectation
    # is checked at the activation row itself. For each observed completion,
    # require cmd_ack to be asserted at that instant.
    follows = False
    verdicts = []
    for w in windows:
        # w.value('cmd_ack') samples the outputs at the activation row.
        val = w.value('cmd_ack')
        if val == 1:
            verdicts.append((True, None, f"cmd_ack asserted at READ completion (edge {w.edge})"))
        else:
            verdicts.append((False, w.edge, "cmd_ack not asserted at READ completion (requirement: 'completes by asserting the cmd_ack output')"))

    return worst(verdicts)

