def decide(trace):
    # Look only at the declared output 'cmd_ack'. Each row is a run-compressed state
    # so a contiguous assertion of cmd_ack appears as one row with 'held' equal to
    # the number of clock edges it lasted. The requirement fixes a duration of
    # exactly one clk cycle, so each cmd_ack==1 run must have held == 1.
    pulses = [r for r in trace if r.get('outputs', {}).get('cmd_ack') == 1]
    if not pulses:
        return (None, None, 'no cmd_ack high observed; the command-complete activation did not occur in this trace')
    # Fail on the first pulse that does not last exactly one clock edge.
    for r in pulses:
        held = r.get('held', 1)
        if held != 1:
            return (False, r.get('edge'), f"cmd_ack was held for {held} edges starting at edge {r.get('edge')}, expected exactly 1")
    return (True, None, f"observed {len(pulses)} cmd_ack pulse(s); each was exactly one clk edge")

