def decide(trace):
    from specflow.refmodel.temporal import (
        TO_END, after, eventually, worst, edges
    )

    # helper: predicate that a row's inputs/outputs hold the given map
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Normalized activation data (transcribed):
    # opens_on: sda_i rise while scl_i == 1
    # inputs: ena == 1
    # aborts_on: nReset == 0 OR rst == 1
    # effect_follows: false  (the expectation applies at the activation row)

    # rows where sda_i rises
    sda_rises = edges(trace, "sda_i", "rise")

    # opening predicate: ena==1 and sda rise while scl_i input is 1
    opens_pred = lambda r: _holds({"ena": 1})(r) and r["edge"] in sda_rises and r["inputs"].get("scl_i") == 1

    # aborts predicate from normalized data
    aborts_pred = _any([{"nReset": 0}, {"rst": 1}])

    # co-extensive window: until is empty in the normalization -> run until activation stops
    windows = after(trace, opens_pred, until=TO_END, aborts=aborts_pred)

    # effect_follows from normalization: false -> expectation applies at the activation row
    follows = False

    # The obligation: al is asserted (driven high) when the STOP-shaped event occurs.
    # This is an obligation (must be true at that instant), so use strong=True.
    verdicts = [
        eventually(w, (lambda r: r["outputs"].get("al") == 1), strong=True, after_activation=follows)
        for w in windows
    ]

    return worst(verdicts)

