def decide(trace):
    """Decide REQ-0029: whenever sda_oen == 0 (and not aborted by reset), sda_o must be 0.

    Returns (ok, edge, detail).
    - ok = False when a non-aborted row with sda_oen==0 has sda_o != 0.
    - ok = None when no non-aborted activation (sda_oen==0) occurs in the trace.
    - ok = True when every non-aborted activation row satisfies sda_o == 0.
    """
    activations = []
    for r in trace:
        # Read only declared ports
        sda_oen = r["outputs"].get("sda_oen")
        # Activation opens when sda_oen == 0
        if sda_oen != 0:
            continue
        # Respect abort conditions from normalized.activation.aborts_on
        # Abort if nReset == 0 or rst == 1; such activations are discarded.
        if r["inputs"].get("nReset") == 0 or r["inputs"].get("rst") == 1:
            continue
        activations.append(r)
        # effect_follows is false: requirement is a level at the activation row
        sda_o = r["outputs"].get("sda_o")
        if sda_o != 0:
            return (False, r.get("edge"), f"sda_o != 0 while sda_oen == 0 at edge {r.get('edge')}")
    if not activations:
        return (None, None, "no non-aborted activation: sda_oen == 0 did not occur in this trace")
    return (True, activations[0].get("edge"), f"sda_oen asserted in {len(activations)} row(s) and sda_o == 0 in all of them")

