def decide(trace):
    # Decide REQ-0012: synchronous active-high reset behaviour.
    # We cannot assume numeric reset values (none are declared), so check that
    # while rst==1 each declared output is stable (driven to and held at its
    # reset/idle value). Return None when rst never occurs.

    outputs = [
        'cmd_ack', 'busy', 'al', 'dout',
        'scl_o', 'scl_oen', 'sda_o', 'sda_oen'
    ]

    # Find contiguous windows where rst==1. Each trace row is a post-rising-edge state.
    windows = []  # list of dicts: {rows: [rows], edge: int, closed: bool}
    i = 0
    n = len(trace)
    while i < n:
        r = trace[i]
        if r.get('inputs', {}).get('rst') == 1:
            start = i
            edge = r.get('edge')
            rows = []
            j = i
            while j < n and trace[j].get('inputs', {}).get('rst') == 1:
                rows.append(trace[j])
                j += 1
            closed = (j < n)
            windows.append({'rows': rows, 'edge': edge, 'closed': closed})
            i = j
        else:
            i += 1

    if not windows:
        return (None, None, 'the activation never occurred: rst was never observed asserted high in this trace')

    # For each window, require every declared output to be constant for the window.
    for w in windows:
        rows = w['rows']
        opener_edge = w['edge']
        # baseline = values in the first row of the window (the synchronous reset event state)
        first = rows[0]
        baseline = {p: first.get('outputs', {}).get(p) for p in outputs}
        # Check subsequent rows for any change
        for rr in rows[1:]:
            for p in outputs:
                val = rr.get('outputs', {}).get(p)
                if val != baseline[p]:
                    detail = (f"output '{p}' changed during reset window: was {baseline[p]} at edge {opener_edge}, "
                              f"changed to {val} at edge {rr.get('edge')}; "
                              "requirement: outputs driven to reset/idle values while rst==1 (rst is asserted high)")
                    return (False, rr.get('edge'), detail)
    # All windows held outputs stable. Pass. Return the edge of the first reset event as localization.
    first_edge = windows[0]['edge']
    return (True, first_edge, 'all declared outputs were stable while rst==1 (synchronous reset windows)')

