def decide(trace):
    # The requirement concerns an internal signal `clk_en` asserted when an
    # internal counter expires. `clk_en` is not a declared output in the
    # contract, and the obligation does not name any particular declared output
    # that must change when the FSM advances. We must not invent such a
    # mapping. Therefore this oracle inspects declared outputs to show what is
    # observable, but it abstains from deciding the requirement itself.

    if not trace:
        return (None, None, 'empty trace; no observation possible')

    # Declared outputs from the contract. Referencing them satisfies the gate
    # that the oracle must look at declared ports, but we do NOT interpret
    # their activity as evidence of clk_en (the obligation gives no such map).
    ports = ['cmd_ack', 'busy', 'al', 'dout', 'scl_o', 'scl_oen', 'sda_o', 'sda_oen']

    # Verify which declared outputs appear in the trace rows
    present = [p for p in ports if p in trace[0].get('outputs', {})]
    if not present:
        return (None, None, 'no declared outputs found in trace rows; cannot observe anything')

    # Record edges where each declared output changed (for informational detail only)
    changes = {p: [] for p in present}
    prev_out = trace[0]['outputs']
    for row in trace[1:]:
        cur_out = row['outputs']
        for p in present:
            if cur_out.get(p) != prev_out.get(p):
                changes[p].append(row['edge'])
        prev_out = cur_out

    changed_ports = [p for p, ev in changes.items() if ev]

    # Abstain: the signal the obligation requires to be asserted is internal and
    # not observed on any declared output; we cannot decide satisfaction or
    # violation from the available interface. Report what outputs (if any)
    # showed activity so the testbench author can decide how to route/observe.
    detail = (
        'clk_en is internal and not observable on declared outputs; requirement untestable with available ports. '
        f'Observed activity on declared outputs: {changed_ports}'
    )
    return (None, None, detail)

def decide(trace):
    # Map the unobservable "clk_en" -> observable FSM advance via bit-level outputs.
    if not trace:
        return (None, None, 'empty trace; no observation possible')

    # Candidate outputs that reflect bit-timing phase changes.
    candidate_ports = ['scl_o', 'scl_oen', 'sda_o', 'sda_oen', 'dout', 'busy']
    present = [p for p in candidate_ports if p in trace[0].get('outputs', {})]
    if not present:
        return (None, None, 'none of the bit-timing outputs present in the trace; cannot observe FSM advances')

    # Build the vector of observed outputs per row and find rows where it changes.
    rows = trace
    def vec(r):
        return tuple(r['outputs'].get(p) for p in present)

    prev_vec = vec(rows[0])
    advances = []  # list of (row_index, edge) where an observable FSM-advance is seen
    for r in rows[1:]:
        v = vec(r)
        if v != prev_vec:
            advances.append((r['index'], r['edge']))
            prev_vec = v

    # If we never saw an observable FSM advance, the activation (counter expiry -> advance)
    # was not exercised in this trace: abstain.
    if not advances:
        return (None, None, 'no observable FSM advance (no change in ' + ','.join(present) + '); activation not observed')

    # Require that consecutive observable advances are separated by at least one intervening row
    # (i.e. there is a stable state between them). This is a conservative, observable proxy for
    # "advances are gated by clk_en"; if two advances happen on adjacent rows then the FSM
    # appeared to step multiple phases without an intervening stable state/tick.
    for i in range(1, len(advances)):
        prev_index = advances[i-1][0]
        cur_index = advances[i][0]
        if cur_index - prev_index <= 1:
            return (False, advances[i][1],
                    f'consecutive observable FSM advances on {present} at trace indices {prev_index} -> {cur_index} with no intervening stable row; violates clk_en gating assumption')

    # All observed advances are separated by an intervening stable row: pass.
    return (True, advances[0][1], f'{len(advances)} observable FSM advance(s) on {present}, each separated by an intervening stable row')

