def decide(trace):
    # Decide REQ-0099: START sequence ends with cmd_ack pulsing for exactly one clock
    # Use only declared ports: inputs: cmd, ena, nReset, rst; outputs: sda_oen, scl_oen, cmd_ack, al

    def activates(r):
        return r.get("inputs", {}).get("cmd") == 1 and r.get("inputs", {}).get("ena") == 1

    def is_aborting(r):
        # abort conditions from normalized block
        return r.get("outputs", {}).get("al", 0) == 1 or r.get("inputs", {}).get("nReset", 1) == 0 or r.get("inputs", {}).get("rst", 0) == 1

    windows = []  # list of (start_idx, close_idx) where close_idx is index of cmd_ack==1, or None/"aborted"/"open"
    i = 0
    N = len(trace)
    while i < N:
        r = trace[i]
        if activates(r) and (i == 0 or not activates(trace[i-1])):
            # rising activation at i
            start = i
            closed = None
            aborted = False
            j = i
            while j < N:
                row = trace[j]
                if is_aborting(row):
                    aborted = True
                    break
                if row.get("outputs", {}).get("cmd_ack", 0) == 1:
                    closed = j
                    break
                j += 1
            if aborted:
                windows.append((start, "aborted"))
            elif closed is None:
                windows.append((start, None))
            else:
                windows.append((start, closed))
            # resume search after this activation opened (non-overlapping as normalized expects)
            i = start + 1
        else:
            i += 1

    if not windows:
        return (None, None, "the START activation (cmd==1 with ena==1) never occurred in this trace")

    any_unknown = False
    # collect failures; return the first failure encountered
    for (start, close) in windows:
        if close == "aborted":
            any_unknown = True
            continue
        if close is None:
            any_unknown = True
            continue
        # closed window from start .. close (inclusive of close). Per normalized.effect_follows=True,
        # the observable sequence is evaluated after the activation row, so search begins at start+1.
        a = start + 1
        b = close  # index where cmd_ack==1
        if a >= b:
            # no rows between activation and the cmd_ack row to observe the sequence
            return (False, trace[b]["edge"], "no intermediate states between START activation and cmd_ack; cannot observe START signalling sequence")

        # 1) find a row in [a, b-1] where both lines read released (1)
        release_idx = None
        for k in range(a, b):
            out = trace[k].get("outputs", {})
            if out.get("sda_oen") == 1 and out.get("scl_oen") == 1:
                release_idx = k
                break
        if release_idx is None:
            return (False, trace[a]["edge"], "did not observe both sda_oen==1 and scl_oen==1 after START activation and before SDA was pulled low")

        # 2) find SDA falling edge after release_idx and before close
        sda_fall = None
        for k in range(release_idx + 1, b):
            prev = trace[k-1].get("outputs", {})
            cur = trace[k].get("outputs", {})
            if prev.get("sda_oen") == 1 and cur.get("sda_oen") == 0:
                sda_fall = k
                break
        if sda_fall is None:
            return (False, trace[release_idx]["edge"], "SDA was not driven low after release while the START sequence was active")

        # At SDA-fall, SCL must be released (==1)
        scl_at_sda_fall = trace[sda_fall].get("outputs", {}).get("scl_oen")
        if scl_at_sda_fall != 1:
            return (False, trace[sda_fall]["edge"], f'SDA fell while SCL was not released (scl_oen={scl_at_sda_fall}); START requires SDA low while SCL is high')

        # 3) find SCL falling edge after sda_fall and before close
        scl_fall = None
        for k in range(sda_fall + 1, b):
            prev = trace[k-1].get("outputs", {})
            cur = trace[k].get("outputs", {})
            if prev.get("scl_oen") == 1 and cur.get("scl_oen") == 0:
                scl_fall = k
                break
        if scl_fall is None:
            return (False, trace[sda_fall]["edge"], "SCL was not driven low after SDA was pulled low and before cmd_ack; START requires SCL pulled low after the START condition")

        # 4) check cmd_ack pulse at close is a single-clock pulse
        cmd_edge = trace[b]
        # cmd_ack must have risen at b (previous row 0 -> 1)
        prev_cmd = trace[b-1].get("outputs", {}).get("cmd_ack", 0)
        cur_cmd = cmd_edge.get("outputs", {}).get("cmd_ack", 0)
        if prev_cmd != 0 or cur_cmd != 1:
            return (False, cmd_edge["edge"], "cmd_ack did not rise at the closing row as expected")
        # the pulse must last exactly one clock: the held value at that row must be 1 and next row must return to 0
        if cmd_edge.get("held", 1) != 1:
            return (False, cmd_edge["edge"], f'cmd_ack held for {cmd_edge.get("held", 1)} edges, expected exactly 1')
        if b + 1 >= N:
            # cannot observe the fall of cmd_ack -> incomplete evidence
            return (None, None, "cmd_ack rose at end of trace; cannot confirm it was high for exactly one clock")
        next_cmd = trace[b+1].get("outputs", {}).get("cmd_ack", 0)
        if next_cmd != 0:
            return (False, trace[b+1]["edge"], "cmd_ack did not return to 0 immediately after one clock as required")

        # ordering: ensure release_idx < sda_fall < scl_fall < b
        if not (release_idx < sda_fall < scl_fall < b):
            return (False, trace[release_idx]["edge"], "observed events did not occur in the required order: release -> SDA fall -> SCL fall -> cmd_ack")

        # if we reach here this window satisfies the obligation; check next window
    # fold results: if we saw any unknown windows but no failures, return unknown
    # (we already returned on failures). If here, all closed windows passed.
    for (start, close) in windows:
        if close == "aborted" or close is None:
            return (None, None, "one or more START attempts were aborted or incomplete; no conclusive failure seen")
    # all windows closed and passed: return True anchored to the first cmd_ack edge observed
    for (start, close) in windows:
        if isinstance(close, int):
            return (True, trace[close]["edge"], f'START sequences completed; cmd_ack observed at edge {trace[close]["edge"]} as single-cycle pulse')
    return (None, None, "no closed START windows found")

