def decide(trace):
    """
    Trigger on an observable FSM advance: any change to a declared FSM-driven
    output between consecutive distinct states. If the trace carries a
    signal named 'clk_en' (either in inputs or outputs) use it as the gating
    signal required by the obligation: fail when an observable FSM advance
    occurs on a row where clk_en == 0. If 'clk_en' does not appear in the
    trace, the obligation is untestable at this interface and we return None.

    Returns (ok, edge, detail).
    """
    # Declared outputs plausibly driven by the FSM
    fsm_outputs = [
        'cmd_ack', 'busy', 'al', 'dout',
        'scl_o', 'scl_oen', 'sda_o', 'sda_oen'
    ]

    if len(trace) < 2:
        return (None, None, 'trace too short to observe state changes')

    change_events = []  # list of (index, edge, row) where an FSM-driven output changed
    clk_en_seen = False

    for i in range(1, len(trace)):
        prev = trace[i-1]
        curr = trace[i]

        # note whether clk_en appears anywhere in the trace rows we inspect
        if 'clk_en' in curr.get('inputs', {}) or 'clk_en' in curr.get('outputs', {}):
            clk_en_seen = True

        # detect any change to the listed FSM-driven outputs between distinct states
        changed = False
        for p in fsm_outputs:
            if prev.get('outputs', {}).get(p) != curr.get('outputs', {}).get(p):
                changed = True
                break
        if changed:
            change_events.append((i, curr['edge'], curr))

    if not change_events:
        return (None, None,
                "undecidable: no observable FSM-driven output changes (cmd_ack/busy/al/dout/scl_o/scl_oen/sda_o/sda_oen) detected in this trace; 'clk_en' is internal and not observable here")

    first_idx, first_edge, first_row = change_events[0]

    if not clk_en_seen:
        # We observed an FSM-driven change but the trace contains no clk_en.
        # The obligation references clk_en and cannot be decided without it.
        return (None, first_edge,
                "undecidable: observed FSM-driven output change at edge {} but 'clk_en' is not present in the trace; provide a probe or map clk_en to a declared port".format(first_edge))

    # clk_en does appear somewhere in the trace. For each observed FSM-driven
    # change require clk_en == 1 at that row. We read clk_en where it appears
    # in the row (inputs preferred, then outputs) and fail on the first violation.
    for idx, edge, row in change_events:
        # prefer inputs then outputs if both present
        clk_val = None
        if 'inputs' in row and 'clk_en' in row['inputs']:
            clk_val = row['inputs']['clk_en']
        elif 'outputs' in row and 'clk_en' in row['outputs']:
            clk_val = row['outputs']['clk_en']

        # If for some reason clk_en is missing at this particular row, treat
        # that row as undecidable rather than assuming a value.
        if clk_val is None:
            return (None, edge,
                    "undecidable: FSM-driven change at edge {} but 'clk_en' missing at that row".format(edge))

        if clk_val != 1:
            return (False, edge,
                    "violation: FSM-driven outputs changed at edge {} while clk_en == {}".format(edge, clk_val))

    # All observed FSM-driven changes were gated by clk_en == 1
    return (True, change_events[0][1], "all observed FSM-driven changes occurred while clk_en == 1 (checked at {} observed change(s))".format(len(change_events)))

REQ-0113.source:
def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, pulse, worst

    # Transcribe the normalized activation: opens when ena==1, aborts on reset.
    activation_inputs = {"ena": 1}
    aborts_on = [{"nReset": 0}, {"rst": 1}]
    follows = False  # normalized.activation.effect_follows

    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    applies = _holds(activation_inputs)
    aborts = _any(aborts_on)

    # The normalized activation has an empty 'until', so the window is co-extensive
    # with the activation -> until=TO_END
    windows = after(trace, applies, until=TO_END, aborts=aborts)

    # Expectation: cmd_ack is driven high for exactly one clk cycle. Use pulse
    # which requires a rise then a fall within the window and that the active
    # width equals 1 edge. Pass after_activation=follows as normalized.
    checks = [pulse(w, "cmd_ack", width=1, active=1, after_activation=follows)
              for w in windows]
    return worst(checks)

