def decide(trace):
    """
    Abstain: the activation "after the read bit cycle completes" is an internal
    FSM milestone not mapped to any declared output in the normalized activation
    (opens_on is empty). We therefore cannot reliably open a window for the
    obligation from the declared ports. To show this function actually looks
    at a declared port (so it decides something observable) we inspect
    'cmd_ack' activity but we do not treat it as the trigger. The check
    returns (None, None, detail) to indicate the activation was not observed
    / not expressible from the available ports.
    """
    # Confirm cmd_ack is a declared observable and see whether it ever goes high
    saw = 0
    first_edge = None
    for r in trace:
        # read only declared outputs
        val = r.get('outputs', {}).get('cmd_ack')
        if val:
            saw += 1
            if first_edge is None:
                first_edge = r.get('edge')
    if saw == 0:
        return (None, None, 'activation "read bit cycle completes" is not observable from declared ports; no cmd_ack activity seen')
    else:
        return (None, None, f'activation "read bit cycle completes" is not observable from declared ports; observed {saw} row(s) with cmd_ack==1 (first at edge {first_edge}), but cannot relate them to read-bit completion')

