def decide(trace):
    """
    Decide REQ-0043.

    Activation (from normalized data): "another master forces SCL low" -> inputs.scl_i == 0.
    To avoid opening a window on stimulus-only signals (which a design cannot control), qualify the activation with a declared output the DUT drives: treat the activation as rows where
      inputs.scl_i == 0  (external SCL driven low)
    AND
      outputs.scl_oen == 1  (this master is not driving SCL low),
    and ignore rows where reset/abort is active (inputs.nReset == 0 or inputs.rst == 1) using the normalized aborts list.

    The obligation itself describes an internal reload/restart and the normalized form records no observable outputs for it, so this oracle must abstain from passing or failing the effect. It still reports where the activation was seen so the testplan can add observable signals if needed.

    Returns (ok, edge, detail).
    """
    # Helper to read safely from a row
    def in_row(row, kind, name):
        return row.get(kind, {}).get(name)

    activations = []
    for r in trace:
        # ignore rows where an abort (reset) is active per normalized.abort_on
        if in_row(r, 'inputs', 'nReset') == 0 or in_row(r, 'inputs', 'rst') == 1:
            continue
        if in_row(r, 'inputs', 'scl_i') == 0 and in_row(r, 'outputs', 'scl_oen') == 1:
            activations.append(r)

    if not activations:
        return (None, None, 'activation never observed: no row with inputs.scl_i==0 while outputs.scl_oen==1 (no external SCL low seen under the qualification)')

    first = activations[0]
    edge = first.get('edge')

    # The obligation is internal and not mapped to any declared output in the normalized form.
    detail = (
        'abstain: obligation describes an internal timing reload/restart ("reloads its internal timing counter from clk_cnt and restarts its SCL low-period timing")'
        ' which is not observable on any declared output for this requirement; activation seen at edge %s' % edge
    )
    return (None, edge, detail)

def decide(trace):
    """
    Decide REQ-0043 by mapping the internal reload/restart to an observable
    change on scl_o or scl_oen while external SCL is held low.

    Activation (normalized): inputs.scl_i == 0
    Aborts (normalized): inputs.nReset == 0 OR inputs.rst == 1

    Behaviour tested: while scl_i==0 (and not aborted), the DUT must show a
    transition on either outputs.scl_o or outputs.scl_oen (evidence it restarted
    its SCL low-period timing). If a closed window contains no such transition
    -> violation (False). If a window is aborted -> Unknown for that attempt.

    Return (ok, edge, detail).
    """
    # Helpers to read safely
    def inp(r, name):
        return r.get('inputs', {}).get(name)
    def outp(r, name):
        return r.get('outputs', {}).get(name)

    # Build set of edges where scl_o or scl_oen changed (transitions)
    change_edges = set()
    if not trace:
        return (None, None, 'empty trace')
    # Start from second row to compare with previous
    for i in range(1, len(trace)):
        prev = trace[i-1]
        cur = trace[i]
        # Only consider declared outputs
        if prev.get('outputs', {}).get('scl_o') != cur.get('outputs', {}).get('scl_o'):
            change_edges.add(cur.get('edge'))
        if prev.get('outputs', {}).get('scl_oen') != cur.get('outputs', {}).get('scl_oen'):
            change_edges.add(cur.get('edge'))

    # Scan for activation windows: consecutive rows where inputs.scl_i == 0
    i = 0
    windows = []  # list of (start_idx, end_idx_exclusive, aborted_flag)
    while i < len(trace):
        r = trace[i]
        # skip rows where activation doesn't hold
        if inp(r, 'scl_i') != 0:
            i += 1
            continue
        # activation opens here unless aborted immediately
        open_idx = i
        open_edge = r.get('edge')
        aborted = False
        # advance until scl_i != 0 or abort encountered
        j = i
        while j < len(trace):
            row = trace[j]
            # if an abort condition becomes true inside the window, this attempt is aborted
            if inp(row, 'nReset') == 0 or inp(row, 'rst') == 1:
                aborted = True
                # window is considered aborted at the row where abort asserted
                windows.append((open_idx, j + 1, True))
                break
            # window continues while scl_i == 0
            if inp(row, 'scl_i') == 0:
                j += 1
                continue
            else:
                # scl_i returned high -> closed window ends at j (exclusive)
                windows.append((open_idx, j, False))
                break
        else:
            # reached end of trace while scl_i still low -> closed window that ran to end
            windows.append((open_idx, len(trace), False))
        # resume scanning after this window
        i = (j + 1) if j >= i else i + 1

    if not windows:
        return (None, None, 'activation never observed: no row with inputs.scl_i == 0')

    # Evaluate each window and fold to worst: any False -> fail; else any True -> pass; else Unknown
    any_true_edge = None
    any_unknown_edge = None
    for (s_idx, e_idx, aborted) in windows:
        open_edge = trace[s_idx].get('edge')
        if aborted:
            # unknown attempt
            if any_unknown_edge is None:
                any_unknown_edge = open_edge
            continue
        # window rows are trace[s_idx:e_idx]
        # check if any transition edge lies inside this window (use edge numbers of row where change was observed)
        window_edges = {trace[k].get('edge') for k in range(s_idx, e_idx)}
        intersect = window_edges & change_edges
        if intersect:
            # success for this attempt; record the earliest transition edge in window
            first_change_edge = min(intersect)
            if any_true_edge is None:
                any_true_edge = first_change_edge
            # continue checking other windows because a later window might fail
            continue
        else:
            # no visible transition in a closed (non-aborted) window -> violation
            detail = (f'Violation: activation at edge {open_edge} (inputs.scl_i==0) produced no transition ' 
                      f'on scl_o or scl_oen while scl_i stayed low')
            return (False, open_edge, detail)

    # No violations found across windows
    if any_true_edge is not None:
        return (True, any_true_edge, f'evidence: transition on scl_o/scl_oen observed at edge {any_true_edge} during an SCL-low window')
    # no True, but at least one aborted window -> Unknown
    if any_unknown_edge is not None:
        return (None, any_unknown_edge, 'attempt(s) aborted by reset/rst before any SCL-output transition could be observed')
    # Should not reach here, but be defensive
    return (None, None, 'no decisive evidence')

