def decide(trace):
    """
    Decide REQ-0051: during the (observable) arbitration-checking window (ena==1, nReset==1, rst==0, sda_i==0) the output al must be asserted (al==1) sometime while that window holds. Abort on nReset==0 or rst==1.

    Returns (ok, edge, detail).
    """
    # activation predicate taken from normalized.activation.inputs
    def holds_activation(row):
        return (
            row['inputs'].get('ena') == 1 and
            row['inputs'].get('nReset') == 1 and
            row['inputs'].get('rst') == 0 and
            row['inputs'].get('sda_i') == 0
        )

    # abort predicates from activation.aborts_on: abort on nReset==0 or rst==1
    def is_abort(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    windows = []  # list of lists of rows (each window is contiguous rows where activation holds)
    i = 0
    N = len(trace)
    while i < N:
        r = trace[i]
        if holds_activation(r):
            # start a window at i
            start = i
            wnd = []
            while i < N:
                row = trace[i]
                # if abort occurs at this row the attempt is moot; stop including it
                if is_abort(row):
                    break
                if not holds_activation(row):
                    break
                wnd.append(row)
                i += 1
            windows.append(wnd)
            # continue scan after the row that ended the window (do not skip any rows)
            continue
        i += 1

    if not windows:
        # activation never occurred in this trace
        return (None, None, 'the activation window (ena==1, nReset==1, rst==0, sda_i==0) never occurred')

    # For each window, check whether al==1 appears at some row
    for wnd in windows:
        if any(r['outputs'].get('al') == 1 for r in wnd):
            # find first row in this window where al==1 and return success at that edge
            for r in wnd:
                if r['outputs'].get('al') == 1:
                    return (True, r['edge'], "al asserted during arbitration-checking (matched requirement: 'during SDA arbitration checking the controller expects SDA released high but filtered SDA is observed low')")
    # At least one window occurred but none showed al asserted: this violates the obligation
    first_window_edge = windows[0][0]['edge'] if windows[0] else trace[0]['edge']
    return (False, first_window_edge, "no al assertion seen in arbitration window(s) (requirement: 'during SDA arbitration checking the controller expects SDA released high but filtered SDA is observed low')")

REQ-0076.source:
def decide(trace):
    # REQ-0076 names internal signals (sSCL, sSDA) and asserts a modelling/definition choice
    # rather than any observable behaviour on declared ports. Such a clause cannot be
    # decided from a trace that only contains declared ports. We therefore return None
    # (the activation never observed / not decidable) but first touch declared outputs so
    # this oracle names observable ports rather than none at all.
    if not trace:
        return (None, None, 'REQ-0076: empty trace; cannot observe internal signals sSCL/sSDA')
    # Inspect the first row's declared outputs to show the oracle looked at observable ports.
    row = trace[0]
    outputs = row.get('outputs', {})
    observed_ports = {p: (p in outputs) for p in ('scl_oen', 'sda_oen', 'scl_o', 'sda_o', 'dout', 'busy', 'cmd_ack')}
    # The requirement makes no claim about these declared ports itself; it names internal signals
    # only. According to the oracle rules we must not invent an observable effect from the
    # surrounding text, so the honest answer is undecided (None).
    return (None, None, 'REQ-0076 names internal signals sSCL/sSDA; no direct observable constraint on declared ports. Declared outputs checked: ' + str(observed_ports))

REQ-0102.source:
def decide(trace):
    # helper: activation holds when cmd==3 and ena==1 (from normalized.activation)
    def _activation_holds(r):
        return r.get("inputs", {}).get("cmd") == 3 and r.get("inputs", {}).get("ena") == 1

    # aborts when any abort condition is true (from normalized.activation.aborts_on)
    def _is_abort(r):
        return r.get("inputs", {}).get("nReset") == 0 or r.get("inputs", {}).get("rst") == 1

    windows = []  # each is dict: {"edge": edge, "rows": [...], "aborted": bool}
    i = 0
    n = len(trace)
    while i < n:
        r = trace[i]
        if _activation_holds(r) and (i == 0 or not _activation_holds(trace[i-1])):
            # open window at i
            start_edge = r.get("edge")
            rows = []
            aborted = False
            j = i
            while j < n and _activation_holds(trace[j]):
                rows.append(trace[j])
                if _is_abort(trace[j]):
                    aborted = True
                    # still collect to the point activation stops; semantics treat aborted windows as UNKNOWN
                j += 1
            windows.append({"edge": start_edge, "rows": rows, "aborted": aborted})
            i = j
        else:
            i += 1

    # No activation at all
    if not windows:
        return (None, None, "the READ activation (cmd==3 && ena==1) never occurred in this trace")

    any_aborted = any(w["aborted"] for w in windows)
    # Check each non-aborted window: sda_oen must be 1 at every row (throughout the window)
    for w in windows:
        if w["aborted"]:
            continue
        for row in w["rows"]:
            val = row.get("outputs", {}).get("sda_oen")
            # treat missing key as unknown value -> consider it as not driven high
            if val != 1:
                return (False, w["edge"], f'sda_oen != 1 at edge {row.get("edge")}; requirement: sda_oen held high for the duration of the READ command')

    # No failures found. If at least one non-aborted window existed then the requirement held for those windows.
    non_aborted_windows = [w for w in windows if not w["aborted"]]
    if non_aborted_windows:
        return (True, None, f'sda_oen was held high throughout {len(non_aborted_windows)} observed READ window(s)')

    # Otherwise every window was aborted -> unknown
    return (None, None, "all READ windows were aborted by reset (nReset==0 or rst==1); outcome UNKNOWN")

REQ-0024.source:
def decide(trace):
    from specflow.refmodel.temporal import after, throughout, edges, worst

    # helper that matches a list-of-alternative simple predicates like
    # [{'nReset':0}, {'rst':1}] -> predicate that is true if any alt holds
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items()
            )
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    # Activation: START shape => SDA falls while SCL is high
    fell = edges(trace, "sda_i", "fall")
    opens = lambda r: (r["edge"] in fell) and r["inputs"].get("scl_i") == 1

    # Close on STOP-shaped edge: SDA rises while SCL is high
    rose = edges(trace, "sda_i", "rise")
    closes = lambda r: (r["edge"] in rose) and r["inputs"].get("scl_i") == 1

    # Abort conditions copied from the normalized activation
    aborts = _any([{"nReset": 0}, {"rst": 1}])

    # Build windows: from START-shaped edge until STOP-shaped edge (or abort)
    windows = after(trace, opens, until=closes, aborts=aborts)

    # The normalized activation says the effect follows the activation row
    follows = True

    # Expectation: busy is 1 for every row of the window (after the activation)
    def busy_is_set(row):
        return row["outputs"].get("busy") == 1

    verdicts = [throughout(w, busy_is_set, after_activation=follows) for w in windows]
    return worst(verdicts)
